operations.replace:
async function syncCombat(combat = globalThis.game?.combat) {
  // Foundry may emit a transient update while advancing a round where the
  // Combat is still started but no current turn/combatant is momentarily
  // available. Preserve the previously observed activation through that
  // gap; otherwise the following valid turn has no previous activation to
  // close and meltdown countdowns never advance.
  if (!combat?.started) {
    observedCombatTurnKey = null;
    observedCombatActorUuid = null;
    return false;
  }

  const currentTurnKey = turnKey(combat);
  if (!currentTurnKey) return false;

  const currentActorUuid = combat?.combatant?.actor?.uuid ?? null;

function handleFrameConnApplicationDeleteToken() {
  renderFrameConnApplication(
    false
  );
}


function handleFrameConnApplicationUpdateActor(
  actor
) {
  if (
    !frameConnApplicationDisplaysActor(
      actor
    )
  ) {
    return false;
  }


  // Actor telemetry is live state. Force the already-open application to
  // rerender on the same Actor update instead of waiting for a combat, token,
  // or control event to refresh the cockpit.
  return renderFrameConnApplication(
    true
  );
}

dangerZoneActive:
  (() => {
    const heat = Number(system.heat?.value);
    const heatCap = Number(system.heat?.max);

    return (
      Number.isFinite(heat) &&
      Number.isFinite(heatCap) &&
      heatCap > 0 &&
      heat >= Math.ceil(heatCap / 2)
    );
  })(),
